package com.logatron.processor.store;
import com.fasterxml.jackson.databind.ObjectMapper;import com.logatron.contracts.ingestion.CanonicalLogEvent;import com.logatron.processor.configuration.IngestionProperties;import com.logatron.processor.observability.ProcessorMetrics;import org.springframework.stereotype.Component;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
@Component public class ClickHouseStore {private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS").withZone(ZoneOffset.UTC);private final HttpClient http;private final ObjectMapper json;private final IngestionProperties p;private final ProcessorMetrics metrics;public ClickHouseStore(ObjectMapper json,IngestionProperties p,ProcessorMetrics metrics){this.json=json;this.p=p;this.metrics=metrics;this.http=HttpClient.newBuilder().connectTimeout(p.clickhouse().requestTimeout()).build();}public void store(List<CanonicalLogEvent> events){if(events.isEmpty())return;List<CanonicalLogEvent> chunk=new ArrayList<>();int bytes=0;for(CanonicalLogEvent e:events){int estimate=e.message().getBytes(StandardCharsets.UTF_8).length+(e.stackTrace()==null?0:e.stackTrace().getBytes(StandardCharsets.UTF_8).length)+2048;if(!chunk.isEmpty()&&(chunk.size()>=p.ingestion().batchSize()||bytes+estimate>p.ingestion().batchBytes())){insert(chunk);chunk.clear();bytes=0;}chunk.add(e);bytes+=estimate;}if(!chunk.isEmpty())insert(chunk);}private void insert(List<CanonicalLogEvent> events){long start=System.nanoTime();try{StringBuilder body=new StringBuilder();for(CanonicalLogEvent e:events)body.append(json.writeValueAsString(row(e))).append('\n');String query="INSERT INTO "+p.clickhouse().database()+".logs_local FORMAT JSONEachRow";URI uri=URI.create(p.clickhouse().url()+"/?query="+URLEncoder.encode(query,StandardCharsets.UTF_8));String auth=Base64.getEncoder().encodeToString((p.clickhouse().user()+":"+p.clickhouse().password()).getBytes(StandardCharsets.UTF_8));HttpRequest req=HttpRequest.newBuilder(uri).timeout(p.clickhouse().requestTimeout()).header("Authorization","Basic "+auth).header("Content-Type","application/x-ndjson").POST(HttpRequest.BodyPublishers.ofString(body.toString())).build();HttpResponse<String> res=http.send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()/100!=2)throw new IllegalStateException("ClickHouse insert failed with status "+res.statusCode()+": "+res.body());metrics.batchSize.record(events.size());metrics.stored.increment(events.size());}catch(Exception x){metrics.clickHouseFailures.increment();throw new IllegalStateException("ClickHouse persistence unavailable",x);}finally{metrics.insertDuration.record(System.nanoTime()-start,java.util.concurrent.TimeUnit.NANOSECONDS);}}private Map<String,Object> row(CanonicalLogEvent e){Map<String,Object>r=new LinkedHashMap<>();r.put("schema_version",e.schemaVersion());r.put("event_id",e.eventId().toString());r.put("timestamp",TIME.format(e.timestamp()));r.put("observed_timestamp",TIME.format(e.observedTimestamp()));r.put("ingested_at",TIME.format(e.ingestedAt()));put(r,"company_id",e.companyId());put(r,"project_id",e.projectId());put(r,"environment_id",e.environmentId());put(r,"server_id",e.serverId());put(r,"service_id",e.serviceId());put(r,"service_instance_id",e.serviceInstanceId());r.put("company",e.company());r.put("project",e.project());r.put("environment",e.environment());r.put("server",e.server());r.put("hostname",e.hostname());r.put("server_ip",e.serverIp());r.put("service",e.service());r.put("service_instance",e.serviceInstance());r.put("log_file",e.logFile());r.put("log_type",e.logType());r.put("level",e.level());r.put("severity_number",e.severityNumber());put(r,"trace_id",e.traceId());put(r,"span_id",e.spanId());put(r,"trace_flags",e.traceFlags());put(r,"request_id",e.requestId());put(r,"correlation_id",e.correlationId());put(r,"transaction_id",e.transactionId());put(r,"order_token",e.orderToken());put(r,"auction_id",e.auctionId());put(r,"logger",e.logger());put(r,"thread",e.thread());r.put("message",e.message());put(r,"exception_type",e.exceptionType());put(r,"stack_trace",e.stackTrace());r.put("attributes",e.attributes());r.put("resource_attributes",e.resourceAttributes());r.put("data_classification",e.dataClassification());r.put("masking_applied",e.maskingApplied()?1:0);r.put("fingerprint",e.fingerprint());r.put("collector_id",e.collectorId());r.put("source_offset",e.sourceOffset());return r;}private void put(Map<String,Object>m,String k,Object v){m.put(k,v==null?null:v.toString());}public boolean ping(){try{HttpRequest req=HttpRequest.newBuilder(URI.create(p.clickhouse().url()+"/ping")).timeout(Duration.ofSeconds(2)).GET().build();return http.send(req,HttpResponse.BodyHandlers.discarding()).statusCode()==200;}catch(Exception e){return false;}}}